package com.axplatform.sheet;
import com.axplatform.common.Problem;import java.util.*;import java.io.*;import java.util.zip.*;import org.junit.jupiter.api.Test;import static org.assertj.core.api.Assertions.*;
class LargeWorkbookTest {
 static Map<String,Object> data(int count){var rows=new ArrayList<List<String>>();var ids=new ArrayList<String>();for(int i=0;i<count;i++){rows.add(List.of(""+i));ids.add("r"+i);}return SheetRules.normalize(Map.of("columns",List.of(Map.of("id","n","label","값","type","NUMBER","unit","","width",160)),"rows",rows,"rowIds",ids));}
 @Test void largeRowsAndLimitsAreEnforcedWithoutTruncation(){assertThat((List<?>)data(50000).get("rows")).hasSize(50000);assertThatThrownBy(()->data(50001)).isInstanceOf(Problem.class);}
 @Test void aiRequiresBoundedScopeAndPreservesUnselectedRows(){var original=data(500);assertThatThrownBy(()->AiSheetScope.range(original,null,null)).isInstanceOf(Problem.class);var scope=AiSheetScope.range(original,201,100);var projected=AiSheetScope.project(original,scope);var next=new LinkedHashMap<>(projected);var rows=new ArrayList<>((List<List<String>>)next.get("rows"));rows.set(0,List.of("999"));next.put("rows",rows);var merged=AiSheetScope.merge(original,next,scope);var result=(List<List<String>>)merged.get("rows");assertThat(result).hasSize(500);assertThat(result.get(199)).containsExactly("199");assertThat(result.get(200)).containsExactly("999");assertThat(result.get(300)).containsExactly("300");assertThat(((List<?>)original.get("rows")).get(200)).isEqualTo(List.of("200"));}
 @Test void aiCannotDeleteReorderOrAddRowsOutsideScope(){var original=data(500);var scope=AiSheetScope.range(original,20,2);var p=new LinkedHashMap<>(AiSheetScope.project(original,scope));p.put("rowIds",List.of("r20","r19"));assertThatThrownBy(()->AiSheetScope.merge(original,p,scope)).isInstanceOf(Problem.class);assertThatThrownBy(()->AiSheetScope.range(original,499,3)).isInstanceOf(Problem.class);assertThatThrownBy(()->AiSheetScope.range(original,1,201)).isInstanceOf(Problem.class);}
 @Test void stylesViewsMergesSurviveRoundTripAndBlankTemplate()throws Exception {var t=new LinkedHashMap<>(data(2));t.put("presentation",Map.of("styles",List.of(Map.of("color","#123456","background","#ABCDEF","bold",true)),"cellStyles",List.of(List.of(0),List.of(0),List.of(0)),"merges",List.of(List.of(1,0,2,0))));t.put("view",Map.of("search","1","column","n","sort","n","direction","desc"));var normalized=SheetRules.normalize(t);assertThat(normalized.get("view")).isEqualTo(t.get("view"));var report=WorkbookRulesTest.reports(XlsxWriter.bytes(t)).get(0);assertThat(((Map<?,?>)report.get("presentation")).get("merges")).isEqualTo(List.of(List.of(1,0,2,0)));assertThat(report.get("presentation").toString()).contains("#123456","#ABCDEF");assertThat(WorkbookRules.template(WorkbookRules.normalize(t))).isNotNull();}
 @Test void unsafePresentationIsRejected(){var t=new LinkedHashMap<>(data(1));t.put("presentation",Map.of("styles",List.of(Map.of("background","url(javascript:bad)"))));assertThatThrownBy(()->SheetRules.normalize(t)).isInstanceOf(Problem.class);t.put("presentation",Map.of("merges",List.of(List.of(0,0,1,0),List.of(1,0,1,0))));assertThatThrownBy(()->SheetRules.normalize(t)).isInstanceOf(Problem.class);}
 @Test void lettersAndFormulasWorkAfterZ()throws Exception {var cols=new ArrayList<Map<String,Object>>();for(int i=0;i<28;i++)cols.add(new LinkedHashMap<>(Map.of("id","c"+i,"label",SheetFormula.letter(i),"type","NUMBER","unit","","width",160)));cols.get(27).put("formula","[c26]*2");var row=new ArrayList<>(Collections.nCopies(28,"3"));var t=SheetRules.normalize(Map.of("columns",cols,"rows",List.of(row),"rowIds",List.of("r1")));var report=WorkbookRulesTest.reports(XlsxWriter.bytes(t)).get(0);assertThat(((List<List<String>>)report.get("rows")).get(0).get(27)).isEqualTo("6");assertThat(SheetFormula.letter(99)).isEqualTo("CV");}
 static byte[] padded(int mb)throws Exception {var fixture=WorkbookRulesTest.fixture(List.of("<row r='1'><c r='A1'><v>1</v></c></row>"),Map.of(),false);var out=new ByteArrayOutputStream();try(var z=new ZipOutputStream(out);var in=new ZipInputStream(new ByteArrayInputStream(fixture))){for(ZipEntry e;(e=in.getNextEntry())!=null;){z.putNextEntry(new ZipEntry(e.getName()));in.transferTo(z);z.closeEntry();}z.putNextEntry(new ZipEntry("xl/calcChain.xml"));byte[] chunk=new byte[1024*1024];Arrays.fill(chunk,(byte)' ');for(int i=0;i<mb;i++)z.write(chunk);z.closeEntry();}return out.toByteArray();}
 @Test void expandedWorkbooksBeyond20MbAreAcceptedButBombsRemainBounded()throws Exception {SheetImport.validatePackage(padded(24));assertThat(WorkbookRulesTest.reports(padded(24)).get(0).get("status")).isEqualTo("READY");var bomb=padded(65);assertThatThrownBy(()->SheetImport.validatePackage(bomb)).isInstanceOf(Problem.class).hasMessageContaining("64MB");}
}
